import csv, glob, os
import numpy as np
from obspy import Stream, Trace, UTCDateTime
import seisbench.models as sbm

# load predicted picks
picked={'P':set(),'S':set()}
with open('/root/results.csv') as f:
    r=csv.DictReader(f)
    for row in r:
        picked[row['phase']].add(row['file_name'])

all_files=[os.path.basename(p) for p in glob.glob('/root/data/*.npz')]
missP=sorted([f for f in all_files if f not in picked['P']])
missS=sorted([f for f in all_files if f not in picked['S']])
print('missing P',len(missP),'missing S',len(missS))

# helpers

def norm_channels(ch_str):
    parts=[p for p in str(ch_str).split(',') if p]
    if len(parts)==3:
        return parts
    if len(parts)>=1 and len(parts[0])>=2:
        base=parts[0][:-1]
        if base:
            return [base+'E', base+'N', base+'Z']
    return ['CH1','CH2','CH3']

def order_channels(chs):
    def key(c):
        s=c[-1] if c else ''
        return {'Z':0,'3':0,'N':1,'2':1,'E':2,'1':2}.get(s, 99)
    return sorted(range(3), key=lambda i: key(chs[i]))

def build_stream(z):
    data=z['data'].astype('float32')
    dt=float(z['dt'])
    chs=norm_channels(z['channels'].item())
    idx=order_channels(chs)
    data=data[:,idx]
    chs=[chs[i] for i in idx]
    st=Stream(); start=UTCDateTime(0)
    for i,c in enumerate(chs):
        tr=Trace(data[:,i].copy())
        tr.stats.delta=dt
        tr.stats.sampling_rate=1/dt
        tr.stats.starttime=start
        tr.stats.channel=c
        tr.data-=tr.data.mean(); s=tr.data.std();
        if s>0: tr.data*=1/s
        st+=tr
    return st

models={'stead':sbm.PhaseNet.from_pretrained('stead'), 'original':sbm.PhaseNet.from_pretrained('original')}

def max_probs(fname):
    z=np.load('/root/data/'+fname, allow_pickle=True)
    st=build_stream(z)
    out={}
    for name,m in models.items():
        ann=m.annotate(st)
        p=next(tr for tr in ann if tr.stats.channel=='PhaseNet_P').data
        s=next(tr for tr in ann if tr.stats.channel=='PhaseNet_S').data
        out[name]=(float(p.max()), float(s.max()))
    return out

print('\nExamples missing P:')
for f in missP[:5]:
    print(f, max_probs(f))
print('\nExamples missing S:')
for f in missS[:5]:
    print(f, max_probs(f))
PY"}

